/**
 * Credits: reads `public/assets/credits.json` (generated by the assets pipeline from
 * assets/licenses.json). Accepted shapes (lenient, so the pipeline can evolve):
 *   { sections: [{ title, items: [{ name, author, license, url }] }] }
 *   { assets:   [{ file, title?, author?, license, source? | url? }] }
 *   [ ...items ]
 * UI-owned fonts are always listed from FONT_CREDITS.
 */
import { h } from '../dom';
import { Screen } from './screen';

export interface CreditItem {
  name: string;
  author?: string;
  license?: string;
  url?: string;
}
export interface CreditSection {
  title: string;
  items: CreditItem[];
}

export const FONT_CREDITS: CreditItem[] = [
  {
    name: 'Bangers',
    author: 'Vernon Adams',
    license: 'OFL-1.1',
    url: 'https://github.com/googlefonts/bangers',
  },
  {
    name: 'Anton',
    author: 'Vernon Adams',
    license: 'OFL-1.1',
    url: 'https://github.com/googlefonts/AntonFont',
  },
  {
    name: 'Kalam',
    author: 'Indian Type Foundry',
    license: 'OFL-1.1',
    url: 'https://github.com/itfoundry/kalam',
  },
];

type Raw = Record<string, unknown>;
const str = (v: unknown) => (typeof v === 'string' && v.trim() ? v : undefined);

function toItem(r: Raw): CreditItem | null {
  const name = str(r.name) ?? str(r.title) ?? str(r.file)?.split('/').pop();
  if (!name) return null;
  return { name, author: str(r.author), license: str(r.license), url: str(r.url) ?? str(r.source) };
}

export function parseCredits(json: unknown, fallbackTitle: string): CreditSection[] {
  if (Array.isArray(json)) {
    const items = json.map((r) => toItem(r as Raw)).filter((x): x is CreditItem => !!x);
    return items.length ? [{ title: fallbackTitle, items }] : [];
  }
  if (!json || typeof json !== 'object') return [];
  const o = json as Raw;
  if (Array.isArray(o.sections)) {
    return o.sections
      .map((sec) => {
        const so = sec as Raw;
        const items = Array.isArray(so.items)
          ? so.items.map((r) => toItem(r as Raw)).filter((x): x is CreditItem => !!x)
          : [];
        return { title: str(so.title) ?? fallbackTitle, items };
      })
      .filter((sec) => sec.items.length);
  }
  for (const k of ['assets', 'entries', 'items', 'credits']) {
    if (Array.isArray(o[k])) return parseCredits(o[k], fallbackTitle);
  }
  return [];
}

let cache: Promise<unknown> | null = null;
function fetchCredits(): Promise<unknown> {
  cache ??= fetch(`${import.meta.env.BASE_URL}assets/credits.json`, { cache: 'no-cache' })
    .then((r) => (r.ok ? r.json() : null))
    .catch(() => null);
  return cache;
}

export class CreditsScreen extends Screen {
  private onClose: (() => void) | null = null;
  private sections: CreditSection[] | null = null;

  async show(onClose: () => void): Promise<void> {
    this.onClose = onClose;
    this.mount();
    const json = await fetchCredits();
    this.sections = parseCredits(json, this.env.t('credits.assets')).filter(
      (sec) => !sec.items.every((i) => FONT_CREDITS.some((f) => f.name === i.name)),
    );
    if (this.visible) this.refresh();
    this.focusFirst('.cx-btn');
  }

  hide(): void {
    this.unmount();
  }

  close(): void {
    this.hide();
    this.onClose?.();
  }

  protected build(): HTMLElement {
    const t = this.env.t;
    const item = (i: CreditItem) =>
      h(
        'div',
        { class: 'credits-item' },
        h('b', null, i.name),
        i.author ? h('div', null, t('credits.by', { author: i.author })) : null,
        h(
          'small',
          null,
          i.license ? t('credits.license', { license: i.license }) : null,
          i.license && i.url ? ' · ' : null,
          i.url
            ? h(
                'a',
                { href: i.url, target: '_blank', rel: 'noopener noreferrer' },
                i.url.replace(/^https?:\/\//, ''),
              )
            : null,
        ),
      );
    const sec = (title: string, items: CreditItem[]) =>
      h('section', { class: 'credits-sec' }, h('h3', null, title), ...items.map(item));

    const assetSecs = this.sections ?? [];
    const el = h(
      'section',
      {
        class: 'ui-screen scr-modal scr-credits',
        role: 'dialog',
        'aria-modal': 'true',
        'aria-labelledby': 'cr-h',
      },
      h('div', { class: 'cx-scrim' }),
      h(
        'div',
        { class: 'modal-card credits-card' },
        h('h2', { id: 'cr-h', class: 'cx-caption modal-head' }, t('credits.title')),
        h(
          'div',
          { class: 'cx-panel modal-body' },
          h('p', { class: 'credits-sub' }, t('credits.subtitle')),
          ...(assetSecs.length
            ? assetSecs.map((s) => sec(s.title, s.items))
            : [
                h(
                  'section',
                  { class: 'credits-sec' },
                  h('h3', null, t('credits.assets')),
                  h('p', { class: 'credits-item' }, h('small', null, t('credits.empty'))),
                ),
              ]),
          sec(t('credits.fonts'), FONT_CREDITS),
          sec(t('credits.made'), [
            { name: 'three.js', author: 'three.js authors', license: 'MIT', url: 'https://threejs.org' },
          ]),
          h('div', { class: 'credits-thanks' }, t('credits.thanks')),
          h(
            'div',
            { class: 'modal-foot' },
            this.btn(h('button', { class: 'cx-btn primary' }, t('common.close')), () => this.close()),
          ),
        ),
      ),
    );
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        this.close();
      }
    });
    return el;
  }
}
